lemmas.precompositionCoequalizes:
{i.A = i.A₁ : Obj} {i.B = i.B₁ : Obj}
{h = h₁ : i.A₁ ⇒ i.B₁} {i = i₁ : i.A₁ ⇒ i.B₁}
(e₂ : Coequalizer h₁ i₁) {C = C₁ : Obj}
(w : Coequalizer.obj e₂ ⇒ C₁) →
(w ∘ Coequalizer.arr e₂) ∘ h₁ ≈ (w ∘ Coequalizer.arr e₂) ∘ i₁

