lemmas.∘-resp-≈:
{A B : Obj} {C = C₁ : Obj} {f = D : B ⇒ C₁} {h = f : B ⇒ C₁}
{g : A ⇒ B} {i = h₁ : A ⇒ B} →
D ≈ f → g ≈ h₁ → D ∘ g ≈ f ∘ h₁

lemmas.Coequalizer.equality:
{A B : Obj} {f = C₁ : A ⇒ B} {g = D : A ⇒ B}
(r : Coequalizer C₁ D) →
r .Coequalizer.arr ∘ C₁ ≈ r .Coequalizer.arr ∘ D

